const row = $input.first().json || {};

// The sheet row is the source of truth, and the job id in the request must match it
const found = Boolean(row.applicationId) && row.applicationId === req.applicationId && row.jobId === req.jobId;
const canScore = found && row.status === 'Recieved';

// The file id comes from the saved row, never from the request
const m = String(row.cvLink || '').match(/\/d\/([\w-]+)/);

return [{ json: { canScore, row, fileId: row.cvFileId || (m ? m[1] : '') } }];

const req = $input.first().json;
const headers = req.headers || {};
const body = req.body || {};

// The fixed part of the secret, exactly as it is added after the two IDs in the intake workflow
const SHARED_SECRET = '{r-4a_W&GsXx|J2U';

const applicationId = String(body.application_id || '').trim();
const jobId = String(body.job_id || '').trim();
const received = String(headers['secret'] || '');
const expected = applicationId + jobId + SHARED_SECRET;

// Compares every character, so the time taken doesn't reveal how much matched
function same(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

let error = '';
if (!/^APP-\d{8}-[A-Z2-9]{5}$/.test(applicationId)) error = 'Invalid application id';
else if (!/^JOB-\d{8}-[A-Z2-9]{4}$/.test(jobId)) error = 'Invalid job id';
else if (!SHARED_SECRET || SHARED_SECRET.startsWith('PASTE')) error = 'Secret is not configured';
else if (!same(received, expected)) error = 'Wrong secret';

return [{ json: { valid: error === '', error, applicationId, jobId } }];

